            return izquierda;
        }
    }
}

int leer_expresion(Lector_tokens& lector, const Tabla_nombres& tabla, int profundidad) {
    return continuar_expresion(leer_termino(lector, tabla, profundidad), lector, tabla, profundidad);
}

int leer_definicion(Lector_tokens& lector, Tabla_nombres& candidata) {
    const Token destino = lector.leer();
    if (destino.clase != nombre) {
        lector.devolver(destino);
        throw std::runtime_error("Se esperaba un nombre");
    }
    const Token igual = lector.leer();
    if (igual.clase != '=') {
        lector.devolver(igual);
        throw std::runtime_error("Se esperaba =");
    }
    const int valor = leer_expresion(lector, candidata, 0);
    candidata.definir(destino.texto, valor);
    return valor;
}

int leer_sentencia(Lector_tokens& lector, Tabla_nombres& candidata) {
    const Token primero = lector.leer();
    if (primero.clase == declaracion) {
        return leer_definicion(lector, candidata);
    }
    if (primero.clase == nombre) {
        const Token siguiente = lector.leer();
        if (siguiente.clase == '=') {
            const int valor = leer_expresion(lector, candidata, 0);
            candidata.asignar(primero.texto, valor);
            return valor;
        }
        lector.devolver(siguiente);
        const int inicial = candidata.consultar(primero.texto);
        const int termino = continuar_termino(inicial, lector, candidata, 0);
        return continuar_expresion(termino, lector, candidata, 0);
    }
    lector.devolver(primero);
    return leer_expresion(lector, candidata, 0);
}

int leer_operacion(Lector_tokens& lector, Tabla_nombres& tabla) {
    Tabla_nombres candidata = tabla;
    const int valor = leer_sentencia(lector, candidata);
    const Token fin = lector.leer();
    if (fin.clase != ';') {
        lector.devolver(fin);
        throw std::runtime_error("Se esperaba ;");
    }
