    return valor;
}

int main() {
    const std::string texto{"crea t=8;t/3%2+4;t=t+1;t*2;"};
    Lector_tokens lector{texto};
    Tabla_nombres tabla;
    int aceptadas = 0;
    int rechazadas = 0;
    while (true) {
        try {
