    if (token.clase == '-') {
        const int valor = leer_unidad(lector, tabla, profundidad + 1);
        return resultado_en_dominio(-valor);
    }
    if (token.clase == '(') {
        const int valor = leer_expresion(lector, tabla, profundidad + 1);
        const Token cierre = lector.leer();
        if (cierre.clase != ')') {
