int leer_unidad(Lector_tokens& lector, const Tabla_nombres& tabla, int profundidad) {
    if (profundidad > 8) throw std::runtime_error("Profundidad excedida");
    const Token token = lector.leer();
    if (token.clase == numero) return token.valor;
    if (token.clase == nombre) return tabla.consultar(token.texto);
    if (token.clase == '+') return leer_unidad(lector, tabla, profundidad + 1);
    if (token.clase == '-') {
        const int valor = leer_unidad(lector, tabla, profundidad + 1);
        return resultado_en_dominio(-valor);
    }
    if (token.clase == '(') {
        const int valor = leer_expresion(lector, tabla, profundidad + 1);
        const Token cierre = lector.leer();
        if (cierre.clase != ')') {
            lector.devolver(cierre);
            throw std::runtime_error("Se esperaba )");
        }
        return valor;
    }
    lector.devolver(token);
    throw std::runtime_error("Se esperaba una unidad");
}

int continuar_termino(int izquierda, Lector_tokens& lector,
        const Tabla_nombres& tabla, int profundidad) {
    while (true) {
        const Token token = lector.leer();
        if (token.clase == '*' || token.clase == '/' || token.clase == '%') {
            const int derecha = leer_unidad(lector, tabla, profundidad);
            if ((token.clase == '/' || token.clase == '%') && derecha == 0) {
                throw std::runtime_error("Divisor cero");
            }
            if (token.clase == '*') izquierda = resultado_en_dominio(izquierda * derecha);
            else if (token.clase == '/') izquierda = resultado_en_dominio(izquierda / derecha);
            else izquierda = resultado_en_dominio(izquierda % derecha);
        } else {
            lector.devolver(token);
            return izquierda;
        }
    }
}

int leer_termino(Lector_tokens& lector, const Tabla_nombres& tabla, int profundidad) {
    return continuar_termino(leer_unidad(lector, tabla, profundidad), lector, tabla, profundidad);
}

int continuar_expresion(int izquierda, Lector_tokens& lector,
