    while (true) {
        const Token token = lector.leer();
        if (token.clase == '+' || token.clase == '-') {
            const int derecha = leer_termino(lector, tabla, profundidad);
            if (token.clase == '+') izquierda = resultado_en_dominio(izquierda + derecha);
